return [
  {
    json: {
      source_name: 'Pink Zadruga',
      source_url: 'https://www.pink.rs/zadruga',
      category: 'Elita'
    }
  },
  {
    json: {
      source_name: 'Republika Elita',
      source_url: 'https://www.republika.rs/elita-9-farmeri',
      category: 'Elita'
    }
  }
];

const fetchItems = $input.all();
const sourceItems = $('Define News Source1').all();

function getBaseUrl(url) {
  try {
    return new URL(url).origin;
  } catch (error) {
    return '';
  }
}

function cleanText(value) {
  return String(value || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#x27;/g, "'")
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeUrl(href, baseUrl) {
  if (!href) return '';

  href = String(href).trim();

  if (href.startsWith('http')) {
    return href.split('?')[0];
  }

  if (href.startsWith('//')) {
    return 'https:' + href.split('?')[0];
  }

  if (href.startsWith('/')) {
    return baseUrl + href.split('?')[0];
  }

  return '';
}

function isValidArticle(url, title, baseUrl) {
  if (!url || !title) return false;
  if (title.length < 25) return false;

  const lowerUrl = url.toLowerCase();
  const lowerTitle = title.toLowerCase();

  const domain = baseUrl
    .replace('https://', '')
    .replace('http://', '')
    .toLowerCase();

  if (domain && !lowerUrl.includes(domain)) return false;

  const badUrlParts = [
    '/tag/',
    '/video/',
    '/autor/',
    '/login',
    '/register',
    '/newsletter',
    '/privacy',
    '/terms',
    '#',
    'javascript:',
    'mailto:'
  ];

  for (const bad of badUrlParts) {
    if (lowerUrl.includes(bad)) return false;
  }

  const badTitleParts = [
    'facebook',
    'instagram',
    'whatsapp',
    'viber',
    'google news',
    'najnovije vesti',
    'najčitanije',
    'marketing',
    'oglasi',
    'prijavite se',
    'registrujte se',
    'pretplatite se',
    'tv uživo',
    'naslovna'
  ];

  for (const bad of badTitleParts) {
    if (lowerTitle.includes(bad)) return false;
  }

  return true;
}

const allLinks = [];

for (let i = 0; i < fetchItems.length; i++) {
  const fetchJson = fetchItems[i].json;
  const sourceJson = sourceItems[i]?.json || {};

  const sourceName =
    fetchJson.source_name ||
    sourceJson.source_name ||
    'Nepoznat izvor';

  const sourceUrl =
    fetchJson.source_url ||
    sourceJson.source_url ||
    '';

  const category =
    fetchJson.category ||
    sourceJson.category ||
    'Elita';

  // Ako je portal vratio 403/grešku, preskoči ga
  if (fetchJson.error || fetchJson.status === 403 || fetchJson.code === 'ERR_BAD_REQUEST') {
    continue;
  }

  const html =
    fetchJson.data ??
    fetchJson.body ??
    fetchJson.html ??
    fetchJson.response ??
    fetchJson.text ??
    '';

  if (!html || String(html).length < 500) {
    continue;
  }

  const baseUrl = getBaseUrl(sourceUrl);

  const anchorRegex = /<a\b[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;

  let match;

  while ((match = anchorRegex.exec(html)) !== null) {
    const url = normalizeUrl(match[1], baseUrl);
    const title = cleanText(match[2]);

    if (!isValidArticle(url, title, baseUrl)) continue;

    allLinks.push({
      source_name: sourceName,
      source_url: sourceUrl,
      category,
      title,
      url
    });
  }
}

const unique = [];
const seen = new Set();

for (const item of allLinks) {
  const key = item.url.toLowerCase();

  if (seen.has(key)) continue;

  seen.add(key);
  unique.push(item);
}

if (!unique.length) {
  throw new Error('Nije pronađena nijedna validna vest iz HTML izvora. Proveri da li su portali blokirali request ili promenili strukturu.');
}

return unique.slice(0, 80).map(item => ({
  json: item
}));

const candidates = $('Code in JavaScript').all().map(item => item.json);
const historyRows = $('Read Published History').all().map(item => item.json);

function normalize(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'dj')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeUrl(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/^https?:\/\/(www\.)?/, '')
    .replace(/\?.*$/, '')
    .replace(/\/$/, '')
    .trim();
}

function words(value) {
  const stopWords = new Set([
    'i', 'je', 'su', 'se', 'sa', 'u', 'na', 'za', 'od', 'do', 'po',
    'kao', 'koji', 'koja', 'koje', 'ovo', 'ona', 'on', 'oni', 'one',
    'sada', 'nakon', 'posle', 'zbog', 'evo', 'foto', 'video',
    'sok', 'šok', 'drama', 'detalji', 'otkriveno', 'poznato',
    'ekskluzivno', 'hitno', 'skandal', 'isplivalo', 'saznajte'
  ]);

  return normalize(value)
    .split(' ')
    .filter(word => word.length >= 4 && !stopWords.has(word));
}

function similarity(a, b) {
  const aWords = new Set(words(a));
  const bWords = new Set(words(b));

  if (!aWords.size || !bWords.size) return 0;

  let overlap = 0;

  for (const word of aWords) {
    if (bWords.has(word)) overlap++;
  }

  return overlap / Math.min(aWords.size, bWords.size);
}

function parseDate(value) {
  const time = Date.parse(value);
  return Number.isNaN(time) ? null : time;
}

const now = Date.now();
const cutoff = now - 48 * 60 * 60 * 1000;

const recentHistory = historyRows.filter(row => {
  const rowTime = parseDate(row.date || row.selected_at || row.created_at || '');

  if (!rowTime) return true;

  return rowTime >= cutoff;
});

const filtered = [];

for (const candidate of candidates) {
  const candidateUrl = normalizeUrl(candidate.url || candidate.source_url || '');
  const candidateTitle = candidate.title || candidate.topic || candidate.original_title || '';

  let isDuplicate = false;
  let duplicateReason = null;

  for (const row of recentHistory) {
    const oldUrl = normalizeUrl(row.source_url || row.url || '');
    const oldTitle = row.topic || row.original_title || row.title || '';

    if (candidateUrl && oldUrl && candidateUrl === oldUrl) {
      isDuplicate = true;
      duplicateReason = 'same_url';
      break;
    }

    const score = similarity(candidateTitle, oldTitle);

    if (score >= 0.45) {
      isDuplicate = true;
      duplicateReason = `similar_title_${score.toFixed(2)}`;
      break;
    }
  }

  if (!isDuplicate) {
    filtered.push(candidate);
  }
}

if (!filtered.length) {
  throw new Error('Svi kandidati su već obrađeni ili previše slični vestima iz poslednjih 48h.');
}

return filtered.map(item => ({
  json: item
}));

const items = $input.all();

function cleanTitle(value) {
  return String(value || '')
    .replace(/\s+/g, ' ')
    .replace(/^\s*[\-\–\—]+\s*/, '')
    .trim();
}

function isGoodCandidate(item) {
  const title = cleanTitle(item.title);
  const url = String(item.url || '').trim();

  if (!title || !url) return false;
  if (title.length < 25) return false;

  const lowerTitle = title.toLowerCase();
  const lowerUrl = url.toLowerCase();

  const badTitles = [
    'najčitanije',
    'najnovije',
    'marketing',
    'oglasi',
    'facebook',
    'instagram',
    'whatsapp',
    'viber',
    'google news',
    'pridružite se',
    'saznajte sve',
    'tv uživo',
    'naslovna'
  ];

  for (const bad of badTitles) {
    if (lowerTitle.includes(bad)) return false;
  }

  const badUrls = [
    '/tag/',
    '/video/',
    '/autor/',
    '/login',
    '/register',
    '/newsletter',
    '/privacy',
    '/terms',
    '#'
  ];

  for (const bad of badUrls) {
    if (lowerUrl.includes(bad)) return false;
  }

  return true;
}

const cleaned = items
  .map(item => ({
    source_name: item.json.source_name || 'Nepoznat izvor',
    source_url: item.json.source_url || '',
    category: item.json.category || 'Elita',
    title: cleanTitle(item.json.title),
    url: String(item.json.url || '').trim()
  }))
  .filter(isGoodCandidate);

const unique = [];
const seenUrls = new Set();
const seenTitles = new Set();

for (const item of cleaned) {
  const urlKey = item.url.toLowerCase();
  const titleKey = item.title.toLowerCase();

  if (seenUrls.has(urlKey)) continue;
  if (seenTitles.has(titleKey)) continue;

  seenUrls.add(urlKey);
  seenTitles.add(titleKey);

  unique.push(item);
}

const bySource = {};

for (const item of unique) {
  if (!bySource[item.source_name]) {
    bySource[item.source_name] = [];
  }

  if (bySource[item.source_name].length < 7) {
    bySource[item.source_name].push(item);
  }
}

const sourceKeys = Object.keys(bySource);
const maxPerSourceLength = Math.max(0, ...sourceKeys.map(key => bySource[key].length));

const interleaved = [];

for (let i = 0; i < maxPerSourceLength; i++) {
  for (const key of sourceKeys) {
    if (bySource[key][i]) {
      interleaved.push(bySource[key][i]);
    }
  }
}

const finalCandidates = interleaved.slice(0, 30);

if (!finalCandidates.length) {
  throw new Error('Nema kandidata posle čišćenja.');
}

return finalCandidates.map(item => ({
  json: item
}));

const items = $input.all();

const candidates = items
  .map((item, index) => {
    const title = String(item.json.title || '').trim();
    const url = String(item.json.url || '').trim();
    const source = String(item.json.source_name || 'Nepoznat izvor').trim();
    const category = String(item.json.category || 'Elita').trim();

    if (!title || !url) return null;

    return {
      rank_input: index + 1,
      title,
      url,
      source,
      category
    };
  })
  .filter(Boolean)
  .slice(0, 10);

if (!candidates.length) {
  throw new Error('Nema kandidata za Hunter evaluaciju.');
}

const candidates_text = candidates
  .map(candidate => {
    return `${candidate.rank_input}. ${candidate.title}
URL: ${candidate.url}
SOURCE: ${candidate.source}
CATEGORY: ${candidate.category}`;
  })
  .join('\n\n');

const sourcesUsed = [...new Set(candidates.map(c => c.source))].join(', ');

return [
  {
    json: {
      source_name: sourcesUsed || 'Više izvora',
      source_url: '',
      category: 'Elita',
      candidate_count: candidates.length,
      candidates,
      candidates_text
    }
  }
];

const agentJson = $('Evaluate Topics for FokusTV').first().json;
const output = agentJson.output || agentJson;
const historyRows = $input.all().map(item => item.json).filter(r => r && Object.keys(r).length > 0);

const topTopics = output.top_topics || [];

if (!Array.isArray(topTopics) || topTopics.length === 0) {
  throw new Error('Hunter nije vratio top_topics.');
}

function normalize(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'dj')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeUrl(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/^https?:\/\/(www\.)?/, '')
    .replace(/\?.*$/, '')
    .replace(/\/$/, '')
    .trim();
}

const stopWords = new Set([
  'i', 'je', 'su', 'se', 'sa', 'u', 'na', 'za', 'od', 'do', 'po',
  'kao', 'koji', 'koja', 'koje', 'ovo', 'ona', 'on', 'oni', 'one',
  'sada', 'nakon', 'posle', 'zbog', 'evo', 'foto', 'video',
  'sok', 'šok', 'drama', 'detalji', 'otkriveno', 'poznato',
  'ekskluzivno', 'hitno', 'skandal', 'isplivalo'
]);

function words(value) {
  return normalize(value).split(' ').filter(w => w.length >= 4 && !stopWords.has(w));
}

function similarity(a, b) {
  const aWords = new Set(words(a));
  const bWords = new Set(words(b));
  if (!aWords.size || !bWords.size) return 0;
  let overlap = 0;
  for (const w of aWords) if (bWords.has(w)) overlap++;
  return overlap / Math.min(aWords.size, bWords.size);
}

function findDuplicate(t) {
  const tUrl = normalizeUrl(t.url || '');
  const titles = [t.topic || '', t.title || ''];
  for (const row of historyRows) {
    const oldUrl = normalizeUrl(row.source_url || row.url || '');
    const oldTitle = row.topic || row.original_title || row.title || '';
    if (tUrl && oldUrl && (tUrl === oldUrl || tUrl.endsWith(oldUrl) || oldUrl.endsWith(tUrl))) {
      return { type: 'same_url', old_title: oldTitle, similarity: 1 };
    }
    const score = Math.max(...titles.map(x => similarity(x, oldTitle)));
    if (score >= 0.45) {
      return { type: 'similar_title', old_title: oldTitle, similarity: score };
    }
  }
  return null;
}

// Rangiraj: prvo best_topic, pa ostale po priority_score
const candidates = [];
if (output.best_topic) candidates.push(output.best_topic);
const sorted = [...topTopics].sort((a, b) => Number(b.priority_score || 0) - Number(a.priority_score || 0));
for (const t of sorted) {
  if (!candidates.some(c => c.url === t.url && c.topic === t.topic)) candidates.push(t);
}

const skipped = [];
let bestTopic = null;
for (const t of candidates) {
  const dup = findDuplicate(t);
  if (dup) {
    skipped.push({ topic: t.topic, url: t.url, reason: dup });
    continue;
  }
  bestTopic = t;
  break;
}

if (!bestTopic) {
  // Sve teme su vec obradjene - nema nove vesti u ovom krugu
  return [];
}

return {
  json: {
    execution_status: 'ok',
    source_name: bestTopic.source || 'Nepoznat izvor',
    source_url: bestTopic.url,
    category: bestTopic.category || 'Elita',
    best_topic: bestTopic,
    top_topics: topTopics,
    skipped_duplicates: skipped,
    reporter_input_preview: {
      topic: bestTopic.topic,
      source: bestTopic.source || 'Nepoznat izvor',
      url: bestTopic.url,
      category: bestTopic.category || 'Elita'
    }
  }
};

const hunterOutput = $('Format Final Output').first().json;
const input = $input.first().json;

const html =
  input.data ??
  input.body ??
  input.html ??
  input.response ??
  input.text ??
  '';

if (!html || String(html).length < 500) {
  throw new Error('Nema dovoljno HTML sadržaja iz Fetch Best Topic Article.');
}

function cleanText(value) {
  return String(value || '')
    .replace(new RegExp('<script[\\s\\S]*?<\\/script>', 'gi'), ' ')
    .replace(new RegExp('<style[\\s\\S]*?<\\/style>', 'gi'), ' ')
    .replace(new RegExp('<noscript[\\s\\S]*?<\\/noscript>', 'gi'), ' ')
    .replace(new RegExp('<svg[\\s\\S]*?<\\/svg>', 'gi'), ' ')
    .replace(new RegExp('<iframe[\\s\\S]*?<\\/iframe>', 'gi'), ' ')
    .replace(new RegExp('<header[\\s\\S]*?<\\/header>', 'gi'), ' ')
    .replace(new RegExp('<footer[\\s\\S]*?<\\/footer>', 'gi'), ' ')
    .replace(new RegExp('<nav[\\s\\S]*?<\\/nav>', 'gi'), ' ')
    .replace(new RegExp('<br\\s*\\/?>', 'gi'), '\n')
    .replace(new RegExp('<\\/p>', 'gi'), '\n')
    .replace(new RegExp('<\\/h1>', 'gi'), '\n')
    .replace(new RegExp('<\\/h2>', 'gi'), '\n')
    .replace(new RegExp('<\\/h3>', 'gi'), '\n')
    .replace(new RegExp('<[^>]+>', 'g'), ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#x27;/g, "'")
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+\n/g, '\n')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]{2,}/g, ' ')
    .trim();
}

const title =
  hunterOutput.best_topic && hunterOutput.best_topic.title ||
  hunterOutput.best_topic && hunterOutput.best_topic.topic ||
  '';

const url = (hunterOutput.best_topic && hunterOutput.best_topic.url) || '';
const source = (hunterOutput.best_topic && hunterOutput.best_topic.source) || 'Nepoznat izvor';
const category = (hunterOutput.best_topic && hunterOutput.best_topic.category) || 'Elita';

let text = cleanText(html);

const lines = text
  .split('\n')
  .map(line => line.trim())
  .filter(Boolean);

const badLineStarts = [
  'TV uživo',
  'Naslovna',
  'Sportal',
  'Zabava',
  'Biznis',
  'Zdravlje',
  'Slobodno vreme',
  'Video',
  'Galerija',
  'Foto:',
  'Najčitanije',
  'Najnovije',
  'Život poznatih',
  'Novinar rubrike',
  'Podeli',
  'Komentari',
  'Pratite nas',
  'Copyright',
  'Sva prava',
  'Impressum'
];

const filteredLines = lines.filter(line => {
  if (line.length < 30) return false;

  for (const bad of badLineStarts) {
    if (line.startsWith(bad)) return false;
  }

  return true;
});

text = filteredLines.join('\n\n').trim();

if (text.length < 400) {
  text = cleanText(html);
}

if (text.length < 300) {
  throw new Error('Izvučeni tekst je prekratak posle čišćenja. Treba ručno proveriti extractor.');
}

return [
  {
    json: {
      ...hunterOutput,
      source_text: text.slice(0, 8000),
      source_text_length: text.length,
      reporter_input_preview: {
        topic: (hunterOutput.best_topic && hunterOutput.best_topic.topic) || title,
        source,
        url,
        category,
        source_text_preview: text.slice(0, 1200)
      }
    }
  }
];

const finalOutput = $('Format Final Output').first().json;
const textOutput = $('Extract Best Topic Text').first().json;
const factsOutput = $('Extract Source Facts').first().json;

const bestTopic = finalOutput.best_topic || {};
const sourceText = String(textOutput.source_text || '').trim();

let sourceFactsRaw =
  factsOutput.output ??
  factsOutput.text ??
  factsOutput.response ??
  factsOutput.result ??
  factsOutput.content ??
  null;

function cleanCodeFence(value) {
  return String(value || '')
    .replace(/^\s*```json\s*/i, '')
    .replace(/^\s*```\s*/i, '')
    .replace(/\s*```\s*$/i, '')
    .trim();
}

// source_facts je samo pomoćni hint i NE koristi ga Reporter/Publisher.
// Zato parsiranje mora biti otporno: ako AI vrati nevalidan JSON,
// nastavljamo sa praznim objektom umesto da rušimo ceo lanac.
let sourceFacts = {};

if (sourceFactsRaw && typeof sourceFactsRaw === 'object') {
  sourceFacts = sourceFactsRaw;
} else if (sourceFactsRaw) {
  let rawText = cleanCodeFence(sourceFactsRaw);
  const firstBrace = rawText.indexOf('{');
  const lastBrace = rawText.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1) {
    rawText = rawText.slice(firstBrace, lastBrace + 1);
  }

  try {
    sourceFacts = JSON.parse(rawText);
  } catch (error) {
    sourceFacts = {};
  }
}

if (!sourceFacts || typeof sourceFacts !== 'object') {
  sourceFacts = {};
}

const url =
  bestTopic.url ||
  finalOutput.source_url ||
  '';

if (!url) {
  throw new Error('Nedostaje URL najbolje teme.');
}

if (!sourceText || sourceText.length < 300) {
  throw new Error('Nedostaje dovoljno source_text sadržaja.');
}

const topic =
  bestTopic.title ||
  bestTopic.topic ||
  (finalOutput.reporter_input_preview && finalOutput.reporter_input_preview.topic) ||
  'Tema iz News Hunter-a';

const source =
  bestTopic.source ||
  finalOutput.source_name ||
  (finalOutput.reporter_input_preview && finalOutput.reporter_input_preview.source) ||
  'Nepoznat izvor';

const category =
  bestTopic.category ||
  finalOutput.category ||
  (finalOutput.reporter_input_preview && finalOutput.reporter_input_preview.category) ||
  'Elita';

const hunterScore =
  bestTopic.priority_score ||
  finalOutput.hunter_score ||
  null;

const hunterReason =
  bestTopic.reason ||
  finalOutput.hunter_reason ||
  '';

const recommendedAngle =
  bestTopic.recommended_angle ||
  finalOutput.recommended_angle ||
  '';

const originalTitle =
  bestTopic.title ||
  topic;

return {
  json: {
    execution_status: 'ready_for_reporter',

    topic,
    source,
    url,
    category,

    source_text: sourceText,
    source_facts: sourceFacts,

    hunter_score: hunterScore,
    hunter_reason: hunterReason,
    recommended_angle: recommendedAngle,

    original_title: originalTitle,

    top_topics: finalOutput.top_topics || [],
    selected_at: new Date().toISOString()
  }
};

const current = $('Prepare Reporter Input').first().json;
const historyRows = $input.all().map(item => item.json);

function normalize(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'dj')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeUrl(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/^https?:\/\/(www\.)?/, '')
    .replace(/\?.*$/, '')
    .replace(/\/$/, '')
    .trim();
}

function words(value) {
  const stopWords = new Set([
    'i', 'je', 'su', 'se', 'sa', 'u', 'na', 'za', 'od', 'do', 'po',
    'kao', 'koji', 'koja', 'koje', 'ovo', 'ona', 'on', 'oni', 'one',
    'sada', 'nakon', 'posle', 'zbog', 'evo', 'foto', 'video',
    'sok', 'šok', 'drama', 'detalji', 'otkriveno', 'poznato',
    'ekskluzivno', 'hitno', 'skandal', 'isplivalo'
  ]);

  return normalize(value)
    .split(' ')
    .filter(word => word.length >= 4 && !stopWords.has(word));
}

function similarity(a, b) {
  const aWords = new Set(words(a));
  const bWords = new Set(words(b));

  if (!aWords.size || !bWords.size) return 0;

  let overlap = 0;

  for (const word of aWords) {
    if (bWords.has(word)) overlap++;
  }

  return overlap / Math.min(aWords.size, bWords.size);
}

const currentTitle = current.topic || current.original_title || '';
const currentUrl = normalizeUrl(current.url || '');

let duplicate = null;

for (const row of historyRows) {
  const oldUrl = normalizeUrl(row.source_url || row.url || '');
  const oldTitle = row.topic || row.original_title || row.title || '';

  if (currentUrl && oldUrl && currentUrl === oldUrl) {
    duplicate = {
      type: 'same_url',
      old_title: oldTitle,
      old_url: oldUrl,
      similarity: 1
    };
    break;
  }

  const score1 = similarity(currentTitle, oldTitle);
  const score2 = similarity(current.original_title || '', oldTitle);
  const finalScore = Math.max(score1, score2);

  if (finalScore >= 0.45) {
    duplicate = {
      type: 'similar_title',
      old_title: oldTitle,
      old_url: oldUrl,
      similarity: finalScore
    };
    break;
  }
}

if (duplicate) {
  return [
    {
      json: {
        ...current,
        editor_approved: false,
        editor_decision: 'reject_duplicate',
        editor_reason: 'Tema je ista ili previše slična već obrađenoj temi.',
        duplicate_match: duplicate
      }
    }
  ];
}

return [
  {
    json: {
      ...current,
      editor_approved: true,
      editor_decision: 'approved',
      editor_reason: 'Tema nije pronađena u istoriji.'
    }
  }
];
